    def __init__(self) -> None:
        self.other = 1
', 'forward_inherited_member': 'class A:
    def __init__(self) -> None:
        self.data = []
        self.other = C().value
        self.data.append(1)
class B(A):
    @property
    def data(self) -> list[int]:
